import test from 'node:test';import assert from 'node:assert/strict';import{generateKeyPairSync,sign,verify}from'node:crypto';import{readFileSync}from'node:fs';import{createPermitKeyring,createInMemoryPermitKeyStore}from'../../src/coreBridge/permit-keyring.js';import{createTrustBundle}from'../../src/coreBridge/trust-bundle.js';import{canonicalizeJcsSafeInteger}from'../../src/coreBridge/permit-issuer.js';
test('trust bundle uses injected offline-root signer and pinned profile hashes',async()=>{let now=1794758400000;const ring=createPermitKeyring({store:createInMemoryPermitKeyStore(),clock:()=>now});await ring.initialize();const k=await ring.generate();await ring.recordBundleIssued(1,now);await ring.acknowledgeBundle(1);await ring.activate(k.kid,1);const root=generateKeyPairSync('ed25519');let called=false;const signer={async signBundle(bytes){called=true;return{rootKid:'root-1',signature:sign(null,bytes,root.privateKey)}}};const schema=readFileSync(new URL('../../../../contracts/core-bridge/authorization-permit.v1.schema.json',import.meta.url)),profile=readFileSync(new URL('../../../../../curl-ai-bridge/tests/fixtures/authorization-permit/v1.0/canonicalization-profile.json',import.meta.url));const b=await createTrustBundle({keyring:ring,rootSigner:signer,rootKid:'root-1',service:'curl-ai-bridge',environment:'local',schemaBytes:schema,canonicalizationProfileBytes:profile,bundleRevision:2,clock:()=>now});assert.equal(called,true);assert.equal(b.payload.audience,'curl-ai-bridge:local');assert.equal(Date.parse(b.payload.expiresAt)-Date.parse(b.payload.issuedAt),300000);assert.equal(b.payload.schemaSha256,'09ea97dc21b22014c99b3f324a6a823356e9018cbe78dbd73ea4244235f7df85');assert.equal(b.payload.canonicalizationProfileSha256,'4635995634c05bf60037f83d3fc8746ad4eb01879f561fdc9553ca791116ba06');assert.equal(verify(null,Buffer.from(canonicalizeJcsSafeInteger(b.payload)),root.publicKey,Buffer.from(b.integrity.signature,'base64url')),true);await assert.rejects(createTrustBundle({keyring:ring,rootKid:'root-1',service:'curl-ai-bridge',environment:'local',schemaBytes:schema,canonicalizationProfileBytes:profile,bundleRevision:2,clock:()=>now}));});
